import type { GameInput, GameSnapshot, ItemKind, MonsterDef, MonsterKind, World, LogEntry, MonsterInstance } from "./types/game.js";
import { ITEM_DEFS } from "./definitions/items.js";
import { session } from "./runtime/session.js";
import { pickup } from "./systems/inventory-system.js";
import { craft } from "./systems/crafting-system.js";
export type { ItemKind, MonsterKind, GameInput, LogEntry, World, MonsterInstance } from "./types/game.js";
export { ITEM_DEFS };
const D: Record<MonsterKind, MonsterDef> = { crawler: { kind: "crawler", name: "Crawler", hp: 10, attack: 4 }, stalker: { kind: "stalker", name: "Stalker", hp: 16, attack: 7 } };
export const monsters = session.monsters;
const emit = (text: string) => { if (session.worldRef) session.worldRef.output.push({ kind: "text", text }); };
const dump = () => { const v=session.vitals,i=session.inventory,c=session.combat; return [`tick=${session.tickCount}`,`hp=${v.hp}/${v.maxHp}`,`wood=${session.mirror.wood}`,`stone=${session.mirror.stone}`,`inv=${i.wood}/${i.stone}/${i.torch}/${i.ration}`,`weapon=${session.equipment.weapon}`,`bonus=${c.attackBonus}`,`buff=${c.torchBuffTicks}`,`alive=${v.alive}`,`monsters=${monsters.length}`,`events=${session.pendingEvents.length}`,`saves=${session.saveCounter}`].join(";"); };
const roll = (a:number,b:number) => a + Math.floor(session.nextRandom()*(b-a+1));
function attack() { if(!session.vitals.alive)return; if(!monsters.length){session.say("nothing to attack");emit("swing at air");return;} const t=monsters[0],d=D[t.kind]; let r=roll(1,20)+session.combat.attackBonus;if(session.combat.torchBuffTicks>0)r+=2;if(r>=12){t.hp-=6+session.combat.attackBonus;session.say(`you strike the ${d.name} (roll ${r})`);if(t.hp<=0){monsters.shift();session.mirror.stone+=2;session.inventory.stone+=2;session.say(`the ${d.name} falls`);}}else session.say(`you miss the ${d.name} (roll ${r})`);emit(`attack roll ${r}`); }
function equip(x:string){if(!session.vitals.alive)return;if(x==="torch"&&session.inventory.torch>0){session.equipment.weapon="torch";session.say("you ready the torch");emit("equipped torch");}else{session.equipment.weapon="fists";session.say("you ready your fists");emit("equipped fists");}}
function eat(){if(!session.vitals.alive)return;const i=session.inventory;if(i.ration<=0){session.say("no rations left");emit("nothing to eat");return;}i.ration--;session.vitals.hp=Math.min(session.vitals.maxHp,session.vitals.hp+15+i.torch);session.say("you eat a ration");emit("ate");}
function spawn(k:MonsterKind){const d=D[k];monsters.push({kind:k,hp:d.hp,attack:d.attack});session.say(`a ${d.name} emerges from the dark`);}
function onKey(k:GameInput){if(!session.vitals.alive)return;if(k==="KeyW")pickup("wood",emit);if(k==="KeyS")pickup("stone",emit);if(k==="KeyC")craft("torch",emit);if(k==="KeyQ")craft("ration",emit);if(k==="KeyF")attack();if(k==="KeyE")eat();if(k==="KeyH"){if(session.worldRef)session.worldRef.output.push({kind:"panel",text:dump()});if(session.equipment.weapon==="fists"&&session.inventory.torch>0)equip("torch");}}
function snapshot():GameSnapshot{const v=session.vitals,c=session.combat;return{tickCount:session.tickCount,hp:v.hp,maxHp:v.maxHp,wood:session.mirror.wood,stone:session.mirror.stone,inventory:{...session.inventory},equippedWeapon:session.equipment.weapon,attackBonus:c.attackBonus,torchBuffTicks:c.torchBuffTicks,alive:v.alive,log:session.log.entries.slice(-20),monsters:monsters.map(m=>({...m})),rngState:session.rngState};}
function restore(raw:string){const d=JSON.parse(raw)as GameSnapshot;session.tickCount=d.tickCount as number;session.vitals={hp:d.hp as number,maxHp:d.maxHp as number,alive:d.alive as boolean};session.mirror={wood:d.wood as number,stone:d.stone as number};session.inventory=d.inventory as typeof session.inventory;session.equipment.weapon=d.equippedWeapon as string;session.combat.attackBonus=d.attackBonus as number;session.combat.torchBuffTicks=d.torchBuffTicks as number;session.log.entries=(d.log as LogEntry[]).map(e=>({...e}));monsters.length=0;for(const m of d.monsters as MonsterInstance[])monsters.push({...m});session.rngState=d.rngState as number;session.say("save restored");}
function tick(){session.tickCount++;const v=session.vitals;if(session.tickCount%5===0){v.hp-=2;if(v.hp<=0&&v.alive){v.alive=false;session.say("you starve");}}if(session.combat.torchBuffTicks>0)session.combat.torchBuffTicks--;const due=session.pendingEvents.filter(e=>e.at===session.tickCount);for(const e of due){session.say(e.message);emit("event");v.hp-=e.damage;if(v.hp<=0&&v.alive){v.alive=false;session.say("you die of your wounds");}}session.pendingEvents=session.pendingEvents.filter(e=>e.at!==session.tickCount);for(const m of monsters){if(m.kind==="crawler"&&session.tickCount%3===0)v.hp--;if(m.kind==="stalker"){v.hp-=3;if(v.hp<=0&&v.alive){v.alive=false;session.say(`the ${D.stalker.name} finishes you`);}}}if(session.tickCount%20===0&&session.log.entries.length%2===0)spawn(session.nextRandom()>.5?"stalker":"crawler");if(session.tickCount%10===0&&session.worldRef&&session.worldRef.storage.get("ventralis:save")!==undefined){session.saveCounter++;session.worldRef.storage.set("ventralis:save",JSON.stringify({...snapshot(),savedAtTick:session.tickCount,saveCounter:session.saveCounter}));}}
export function resetGame(seed:number){session.reset(seed);}
export function initGame(w:World){session.worldRef=w;const raw=w.storage.get("ventralis:save");if(raw)restore(raw);session.say("you wake in the caverns of Ventralis");}
export const gameLoop=tick,keys=onKey;
export const api={run:(n:number)=>{for(let i=0;i<n;i++)tick();},pickup:(k:ItemKind)=>pickup(k,emit),craft:(r:string)=>craft(r,emit),consumeRation:eat,equip,spawn,schedule:(at:number,message:string,damage:number)=>session.pendingEvents.push({at,message,damage}),dump,snapshot,restore,state:()=>({get tick(){return session.tickCount},get hp(){return session.vitals.hp},get alive(){return session.vitals.alive},get wood(){return session.mirror.wood},get stone(){return session.mirror.stone}})};
